static rsRetVal ATTR_NONNULL() rcvMainLoop(struct wrkrInfo_s *const __restrict__ pWrkr) {
    DEFiRet;
    int nfds;
    struct sockaddr_storage frominetPrev;
    struct lstn_s *lstnPrev;
    int bIsPermitted;
    int i = 0;
    struct lstn_s *lstn;

    DBGPRINTF("imudp uses poll() [ex-select]\n");
    /* start "name caching" algo by making sure the previous system indicator
     * is invalidated. */
    bIsPermitted = 0;
    lstnPrev = NULL;
    memset(&frominetPrev, 0, sizeof(frominetPrev));

    /* setup poll() subsystem */
    int nfd = 0;
    for (lstn = lcnfRoot; lstn != NULL; lstn = lstn->next) {
        if (lstn->sock != -1) {
            if (Debug) {
                net.debugListenInfo(lstn->sock, (char *)"UDP");
            }
            ++nfd;
        }
    }
    struct pollfd *const pollfds = calloc(nfd, sizeof(struct pollfd));
    CHKmalloc(pollfds);

    for (lstn = lcnfRoot; lstn != NULL; lstn = lstn->next) {
        assert(i < nfd);
        if (lstn->sock != -1) {
            pollfds[i].fd = lstn->sock;
            pollfds[i].events = POLLIN;
            ++i;
        }
    }

    while (1) {
        DBGPRINTF("--------imudp calling poll() on %d fds\n", nfd);
        nfds = poll(pollfds, nfd, -1);
        if (glbl.GetGlobalInputTermState() == 1) break; /* terminate input! */

        if (nfds < 0) {
            if (errno == EINTR) {
                DBGPRINTF("imudp: EINTR occurred\n");
            } else {
                LogMsg(errno, RS_RET_POLL_ERR, LOG_WARNING,
                       "imudp: poll "
                       "system call failed, may cause further troubles");
            }
            nfds = 0;
        }

        i = 0;
        for (lstn = lcnfRoot; nfds && lstn != NULL; lstn = lstn->next) {
            assert(i < nfd);
            if (lstn->sock != -1) {
                if (glbl.GetGlobalInputTermState() == 1) ABORT_FINALIZE(RS_RET_FORCE_TERM); /* terminate input! */
                if (pollfds[i].revents & POLLIN) {
                    processSocket(pWrkr, lstn, &frominetPrev, &lstnPrev, &bIsPermitted);
                    --nfds;
                }
                ++i;
            }
        }
        /* end of a run, back to loop for next recv() */
    }

finalize_it:
    RETiRet;
}
